$ErrorActionPreference='Stop'; . (Join-Path $PSScriptRoot 'windows_paths.ps1'); $memoryProcessStartup=New-CimInstance -ClassName Win32_ProcessStartup -ClientOnly -Property @{ShowWindow=[uint16]0}; $memoryCommand='"'+(Join-Path $PSScriptRoot 'AI-Memory-Status.exe')+'"'; $memoryLaunch=Invoke-CimMethod -ClassName Win32_Process -MethodName Create -Arguments @{CommandLine=$memoryCommand;ProcessStartupInformation=$memoryProcessStartup}; if ($memoryLaunch.ReturnValue -ne 0) { throw 'Native status-tray launcher failed.' }
